package com.example.app;

import java.sql.SQLException;
import java.util.List;

public final class App {

    public static void main(String[] args) {
        DbConfig config = DbConfig.fromEnvironment();

        try (Database database = Database.connect(config)) {
            List<String> tables = database.listTables();
            System.out.println("Connected to " + config.jdbcUrl());
            System.out.println("Tables:");
            tables.forEach(table -> System.out.println("  - " + table));

            if (args.length > 0) {
                String sql = String.join(" ", args);
                System.out.println();
                System.out.println("Query: " + sql);
                List<String> rows = database.query(sql);
                rows.forEach(row -> System.out.println("  " + row));
            }
        } catch (SQLException e) {
            System.err.println("Database error: " + e.getMessage());
            System.exit(1);
        }
    }
}

package com.example.app;

public record DbConfig(String host, int port, String database, String user, String password) {

    public static DbConfig fromEnvironment() {
        String host = env("DB_HOST", "localhost");
        int port = Integer.parseInt(env("DB_PORT", "3306"));
        String database = env("DB_NAME", "test");
        String user = env("DB_USER", "root");
        String password = env("DB_PASSWORD", "");
        return new DbConfig(host, port, database, user, password);
    }

    public String jdbcUrl() {
        return "jdbc:mysql://" + host + ":" + port + "/" + database
                + "?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC";
    }

    private static String env(String name, String defaultValue) {
        String value = System.getenv(name);
        return (value == null || value.isBlank()) ? defaultValue : value;
    }
}

package com.example.app;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.StringJoiner;

public final class Database implements AutoCloseable {

    private final Connection connection;

    private Database(Connection connection) {
        this.connection = connection;
    }

    public static Database connect(DbConfig config) throws SQLException {
        Connection connection = DriverManager.getConnection(
                config.jdbcUrl(), config.user(), config.password());
        return new Database(connection);
    }

    public List<String> listTables() throws SQLException {
        List<String> tables = new ArrayList<>();
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery("SHOW TABLES")) {
            while (resultSet.next()) {
                tables.add(resultSet.getString(1));
            }
        }
        return tables;
    }

    public List<String> query(String sql) throws SQLException {
        List<String> rows = new ArrayList<>();
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery(sql)) {
            ResultSetMetaData meta = resultSet.getMetaData();
            int columnCount = meta.getColumnCount();
            while (resultSet.next()) {
                StringJoiner joiner = new StringJoiner(", ", "{", "}");
                for (int i = 1; i <= columnCount; i++) {
                    joiner.add(meta.getColumnLabel(i) + "=" + resultSet.getString(i));
                }
                rows.add(joiner.toString());
            }
        }
        return rows;
    }

    @Override
    public void close() throws SQLException {
        connection.close();
    }
}
